




"use strict";

const ConcatenationScope = require("../ConcatenationScope");
const Dependency = require("../Dependency");
const InitFragment = require("../InitFragment");
const RuntimeGlobals = require("../RuntimeGlobals");
const { InlinedUsedName } = require("../optimize/InlineExports");
const makeSerializable = require("../util/makeSerializable");
const { propertyAccess } = require("../util/property");
const ExportBindingInitFragment = require("./ExportBindingInitFragment");
const HarmonyExportInitFragment = require("./HarmonyExportInitFragment");
const NullDependency = require("./NullDependency");

const DEFAULT_EXPORT_NAME = "default";















class HarmonyExportExpressionDependency extends NullDependency {
	







	constructor(range, rangeStatement, prefix, declarationId, constValue) {
		super();
		this.range = range;
		this.rangeStatement = rangeStatement;
		
		this.prefix = prefix;
		this.declarationId = declarationId;
		this.constValue = constValue;
		
		this.isAnonymousDefault = false;
	}

	get type() {
		return "harmony export expression";
	}

	



	getLazyUntil() {
		return Dependency.LAZY_UNTIL_LOCAL;
	}

	



	getLazyName() {
		return DEFAULT_EXPORT_NAME;
	}

	




	getExports(moduleGraph) {
		const module = moduleGraph.getParentModule(this);
		const pureFunctions =
			module &&
			module.buildInfo &&
			 (module.buildInfo).pureFunctions;
		const isPure = Boolean(
			pureFunctions && pureFunctions.has(DEFAULT_EXPORT_NAME)
		);

		return {
			exports: [
				{
					name: DEFAULT_EXPORT_NAME,
					isPure: isPure || undefined,
					inlined: this.constValue
				}
			],
			priority: 1,
			terminalBinding: true,
			dependencies: undefined
		};
	}

	




	getModuleEvaluationSideEffectsState(moduleGraph) {
		
		return false;
	}

	



	serialize(context) {
		context
			.write(this.range)
			.write(this.rangeStatement)
			.write(this.prefix)
			.write(this.declarationId)
			.write(this.isAnonymousDefault)
			.write(this.constValue);
		super.serialize(context);
	}

	



	deserialize(context) {
		this.range = context.read();
		const c1 = context.rest;
		this.rangeStatement = c1.read();
		const c2 = c1.rest;
		this.prefix = c2.read();
		const c3 = c2.rest;
		this.declarationId = c3.read();
		const c4 = c3.rest;
		this.isAnonymousDefault = c4.read();
		const c5 = c4.rest;
		this.constValue = c5.read();
		super.deserialize(c5.rest);
	}
}

makeSerializable(
	HarmonyExportExpressionDependency,
	"webpack/lib/dependencies/HarmonyExportExpressionDependency"
);

HarmonyExportExpressionDependency.Template = class HarmonyExportDependencyTemplate extends (
	NullDependency.Template
) {
	






	apply(
		dependency,
		source,
		{
			module,
			moduleGraph,
			runtimeTemplate,
			runtimeRequirements,
			initFragments,
			runtime,
			concatenationScope
		}
	) {
		const dep =  (dependency);
		const { declarationId } = dep;
		const exportsName = module.exportsArgument;
		if (declarationId) {
			
			let name;
			if (typeof declarationId === "string") {
				name = declarationId;
			} else {
				name = ConcatenationScope.DEFAULT_EXPORT;
				source.replace(
					declarationId.range[0],
					declarationId.range[1] - 1,
					`${declarationId.prefix}${name}${declarationId.suffix}`
				);
			}

			const used = concatenationScope
				? undefined
				: moduleGraph
						.getExportsInfo(module)
						.getUsedName(DEFAULT_EXPORT_NAME, runtime);

			if (concatenationScope) {
				concatenationScope.registerExport(DEFAULT_EXPORT_NAME, name);
			} else if (used) {
				
				const map = new Map();
				map.set(used, `/* export default binding */ ${name}`);
				initFragments.push(new HarmonyExportInitFragment(exportsName, map));
			}

			source.replace(
				dep.rangeStatement[0],
				dep.range[0] - 1,
				`/* harmony default export */ ${dep.prefix}`
			);

			if (
				typeof declarationId !== "string" &&
				dep.isAnonymousDefault &&
				(concatenationScope || used)
			) {
				
				
				runtimeRequirements.add(RuntimeGlobals.setAnonymousDefaultName);
				initFragments.push(
					new InitFragment(
						`${RuntimeGlobals.setAnonymousDefaultName}(${name});\n`,
						InitFragment.STAGE_HARMONY_EXPORTS,
						2
					)
				);
			}
		} else {
			
			let content;
			let name = ConcatenationScope.DEFAULT_EXPORT;
			let defaultIsUsed = Boolean(concatenationScope);
			if (runtimeTemplate.supportsConst()) {
				content = `/* harmony default export */ const ${name} = `;
				if (concatenationScope) {
					concatenationScope.registerExport(DEFAULT_EXPORT_NAME, name);
				} else {
					const used = moduleGraph
						.getExportsInfo(module)
						.getUsedName(DEFAULT_EXPORT_NAME, runtime);
					if (used instanceof InlinedUsedName) {
						content = `/* inlined harmony default export */ const ${name} = `;
					} else if (used) {
						defaultIsUsed = true;
						runtimeRequirements.add(RuntimeGlobals.exports);
						
						const canUseValueBinding =
							 (module.buildInfo)
								.isCircular === false;
						if (canUseValueBinding) {
							initFragments.push(
								new ExportBindingInitFragment(
									exportsName,
									[
										{
											name: used,
											value: `/* export default binding */ ${name}`,
											bindingType: "value"
										}
									],
									true
								)
							);
						} else {
							
							const map = new Map();
							map.set(used, name);
							initFragments.push(
								new HarmonyExportInitFragment(exportsName, map)
							);
						}
					} else {
						content = `/* unused harmony default export */ var ${name} = `;
					}
				}
			} else if (concatenationScope) {
				content = `/* harmony default export */ var ${name} = `;
				concatenationScope.registerExport(DEFAULT_EXPORT_NAME, name);
			} else {
				const used = moduleGraph
					.getExportsInfo(module)
					.getUsedName(DEFAULT_EXPORT_NAME, runtime);
				if (used instanceof InlinedUsedName) {
					content = `/* inlined harmony default export */ var ${name} = `;
				} else if (used) {
					defaultIsUsed = true;
					runtimeRequirements.add(RuntimeGlobals.exports);
					
					
					
					
					name = `${exportsName}${propertyAccess(
						typeof used === "string" ? [used] : used
					)}`;
					content = `/* harmony default export */ ${name} = `;
				} else {
					content = `/* unused harmony default export */ var ${name} = `;
				}
			}

			if (dep.range) {
				source.replace(
					dep.rangeStatement[0],
					dep.range[0] - 1,
					`${content}(${dep.prefix}`
				);
				if (dep.isAnonymousDefault && defaultIsUsed) {
					
					
					runtimeRequirements.add(RuntimeGlobals.setAnonymousDefaultName);
					source.replace(
						dep.range[1],
						dep.rangeStatement[1] - 0.5,
						`);\n${RuntimeGlobals.setAnonymousDefaultName}(${name});`
					);
				} else {
					source.replace(dep.range[1], dep.rangeStatement[1] - 0.5, ");");
				}
				return;
			}

			source.replace(dep.rangeStatement[0], dep.rangeStatement[1] - 1, content);
		}
	}
};

module.exports = HarmonyExportExpressionDependency;
